-- Seeds the FIVE DATE-FREE stock box labels — «Коробка … без дат …» — for
-- every existing organization. They are the second stock family: the same
-- design at the same five sizes, minus «Дата производства» and «Годен до»,
-- with the vertical space those two columns used to occupy given to the SSCC
-- bars (7.6 mm instead of 4.8 mm on the 58×40).
--
-- INSERT-IF-ABSENT, keyed on (tenant_id, name) — the pattern of
-- 0049_default_label_templates.sql, deliberately NOT the force-overwrite of
-- 0050/0052. These five names have never existed in any database, so there is
-- nothing of a tenant's to overwrite: a row can only be missing, never stale.
-- The `WHERE NOT EXISTS` guard therefore does two jobs — it makes the
-- migration idempotent, and it means a tenant who has already created a
-- template under one of these names keeps theirs untouched.
--
-- NOTHING EXISTING IS MODIFIED. The dated five are not re-seeded, not
-- re-specced and not re-pointed; `org_profiles.default_box_label_template_id`
-- is not touched, so every tenant's default box label stays whatever it was.
--
-- The spec jsonb below is GENERATED from `buildDateFreeBoxLabelTemplates()`
-- in `packages/domain/src/labels/defaults.ts`, not hand-written; the drift
-- guard in `packages/domain/test/labels-defaults.test.ts` re-parses this file
-- and deep-compares it against that builder, so the two cannot diverge.

INSERT INTO label_templates (tenant_id, name, spec)
SELECT o.id, t.name, t.spec::jsonb
FROM organization o
CROSS JOIN (VALUES
  ('Коробка 58×40 без дат (203 dpi)', '{"widthMm":58,"heightMm":40,"dpi":203,"language":"zpl","elements":[{"kind":"field","id":"name","xMm":2,"yMm":2,"field":"product.name","fontSizePt":10,"bold":true,"maxWidthMm":54,"maxLines":3},{"kind":"line","id":"sep1","xMm":2,"yMm":18.2,"x2Mm":56,"y2Mm":18.2,"thicknessMm":0.3},{"kind":"text","id":"cap-qty","xMm":2,"yMm":18.8,"text":"Кол-во в упаковке:","fontSizePt":5,"maxWidthMm":18},{"kind":"field","id":"val-qty","xMm":20,"yMm":18.8,"field":"qty","fontSizePt":8,"bold":true,"maxWidthMm":36},{"kind":"line","id":"sep2","xMm":2,"yMm":23.4,"x2Mm":56,"y2Mm":23.4,"thicknessMm":0.3},{"kind":"text","id":"cap-egais","xMm":2,"yMm":24,"text":"Код ЕГАИС:","fontSizePt":5,"maxWidthMm":18},{"kind":"field","id":"val-egais","xMm":20,"yMm":24,"field":"product.egais","fontSizePt":8,"bold":true,"maxWidthMm":36},{"kind":"line","id":"sep3","xMm":2,"yMm":28.6,"x2Mm":56,"y2Mm":28.6,"thicknessMm":0.3},{"kind":"barcode","id":"bc-sscc","xMm":9.5,"yMm":29.2,"format":"code128","data":"sscc","sizeMm":7.6,"moduleWidthMm":0.2502},{"kind":"field","id":"val-sscc","xMm":2,"yMm":37,"field":"sscc","fontSizePt":5,"align":"center","maxWidthMm":54}]}'),
  ('Коробка 58×40 без дат (300 dpi)', '{"widthMm":58,"heightMm":40,"dpi":300,"language":"zpl","elements":[{"kind":"field","id":"name","xMm":2,"yMm":2,"field":"product.name","fontSizePt":10,"bold":true,"maxWidthMm":54,"maxLines":3},{"kind":"line","id":"sep1","xMm":2,"yMm":18.2,"x2Mm":56,"y2Mm":18.2,"thicknessMm":0.3},{"kind":"text","id":"cap-qty","xMm":2,"yMm":18.8,"text":"Кол-во в упаковке:","fontSizePt":5,"maxWidthMm":18},{"kind":"field","id":"val-qty","xMm":20,"yMm":18.8,"field":"qty","fontSizePt":8,"bold":true,"maxWidthMm":36},{"kind":"line","id":"sep2","xMm":2,"yMm":23.4,"x2Mm":56,"y2Mm":23.4,"thicknessMm":0.3},{"kind":"text","id":"cap-egais","xMm":2,"yMm":24,"text":"Код ЕГАИС:","fontSizePt":5,"maxWidthMm":18},{"kind":"field","id":"val-egais","xMm":20,"yMm":24,"field":"product.egais","fontSizePt":8,"bold":true,"maxWidthMm":36},{"kind":"line","id":"sep3","xMm":2,"yMm":28.6,"x2Mm":56,"y2Mm":28.6,"thicknessMm":0.3},{"kind":"barcode","id":"bc-sscc","xMm":9.2,"yMm":29.2,"format":"code128","data":"sscc","sizeMm":7.6,"moduleWidthMm":0.254},{"kind":"field","id":"val-sscc","xMm":2,"yMm":37,"field":"sscc","fontSizePt":5,"align":"center","maxWidthMm":54}]}'),
