  ('Коробка 100×150 без дат (203 dpi)', '{"widthMm":100,"heightMm":150,"dpi":203,"language":"zpl","elements":[{"kind":"field","id":"name","xMm":3.4,"yMm":3.4,"field":"product.name","fontSizePt":17,"bold":true,"maxWidthMm":93.2,"maxLines":3},{"kind":"line","id":"sep1","xMm":3.4,"yMm":31,"x2Mm":96.6,"y2Mm":31,"thicknessMm":0.5},{"kind":"text","id":"cap-qty","xMm":3.4,"yMm":32.1,"text":"Кол-во в упаковке:","fontSizePt":8,"maxWidthMm":31.1},{"kind":"field","id":"val-qty","xMm":34.5,"yMm":32.1,"field":"qty","fontSizePt":14,"bold":true,"maxWidthMm":62.1},{"kind":"line","id":"sep2","xMm":3.4,"yMm":40.1,"x2Mm":96.6,"y2Mm":40.1,"thicknessMm":0.5},{"kind":"text","id":"cap-egais","xMm":3.4,"yMm":41.2,"text":"Код ЕГАИС:","fontSizePt":8,"maxWidthMm":31.1},{"kind":"field","id":"val-egais","xMm":34.5,"yMm":41.2,"field":"product.egais","fontSizePt":14,"bold":true,"maxWidthMm":62.1},{"kind":"line","id":"sep3","xMm":3.4,"yMm":49.2,"x2Mm":96.6,"y2Mm":49.2,"thicknessMm":0.5},{"kind":"barcode","id":"bc-sscc","xMm":11,"yMm":50.3,"format":"code128","data":"sscc","sizeMm":13.5,"moduleWidthMm":0.5005},{"kind":"field","id":"val-sscc","xMm":3.4,"yMm":64.2,"field":"sscc","fontSizePt":8,"align":"center","maxWidthMm":93.2}]}')
) AS t(name, spec)
WHERE NOT EXISTS (
  SELECT 1 FROM label_templates lt
  WHERE lt.tenant_id = o.id AND lt.name = t.name
);
